import React, { useEffect, useRef, useState } from "react";
import { IconSparkles, IconAutomation, IconListCheck, IconFolder, IconSettings, IconPlus, IconArrowRight, IconArrowLeft,
  IconRefresh, IconCheck, IconFileText, IconMovie, IconChevronRight, IconLock, IconDeviceDesktop, IconTrendingUp,
  IconPlayerPause, IconPlayerPlay, IconFolderOpen, IconExternalLink, IconEye, IconLogout, IconSearch, IconScissors, IconDatabase, IconBox } from "@tabler/icons-react";
import { useBasics } from "./basics.ts";
import { Retrieval, type Supplement } from "./Retrieval.tsx";
import { MaterialLibrary, CacheManagement } from "./MaterialViews.tsx";
import { Projects, Tasks } from "./WorkspaceViews.tsx";
import { UnifiedSettings } from "./Settings.tsx";
import { automaticTitle, DEFAULT_OUTPUT, workReady } from "../../../packages/smart-cutter/src/types.ts";
import { request, sourceUrl, mediaUrl, pickDirectory, modeName, originName, duration, dateText, WORK_NAMES, JOB_NAMES,
  ApiError, type AppState, type Work, type Job, type Rule, type OutputSettings, type WorkSummary } from "./api.ts";
import { Button, Badge, Banner, Header, Switch, Steps, Origin, Empty, Modal, MatchBadge, SourcePlayer } from "./components.tsx";

const NAMES = { retrieve: "文案检索", projects: "我的项目", local: "本地素材", materials: "公共素材库", cache: "缓存管理", home: "手动创作", automatic: "自动创作", create: "输入文案", review: "匹配审核", preview: "成片调整", tasks: "任务中心", films: "本地成果", monitor: "博主监控", hot: "热点文案", rules: "自动化规则", settings: "设置" };
type Route = keyof typeof NAMES;
const AUTO: Route[] = ["automatic", "monitor", "hot", "rules"];
const STAGES: Route[] = ["create", "review", "preview"];
const routeFromHash = (): Route => { const name = location.hash.replace("#/", ""); return Object.hasOwn(NAMES, name) ? name as Route : "retrieve"; };
type Dialog = { kind: "account" } | { kind: "hot"; id: string } | { kind: "job" | "film"; id: string } | null;
type Prefs = AppState["settings"];
const ruleDefaults = (): Partial<Rule> => ({ name: "抖音热点 · 原声成片", enabled: false, platform: "douyin", account_group: "", max_age_hours: 24, min_likes: 1000, min_growth_per_hour: 0, execution: "review", daily_limit: 5, candidates_per_run: 2, source_folder: "" });
const numberText = (value: number | null | undefined): string => value === null || value === undefined ? "未知" : value >= 10_000 ? `${(value / 10_000).toFixed(1)} 万` : value.toLocaleString("zh-CN");

export function SmartApp() {
  const [route, setRoute] = useState<Route>(routeFromHash);
  const [state, setState] = useState<AppState | null>(null);
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [busy, setBusy] = useState(false);
  const [work, setWork] = useState<Work | null>(null);
  const [selectedId, setSelectedId] = useState(1);
  const [inputScript, setInputScript] = useState("");
  const [output, setOutput] = useState<OutputSettings>({ ...DEFAULT_OUTPUT });
  const [folders, setFolders] = useState<Array<{ name: string; count: number }>>([]);
  const [dialog, setDialog] = useState<Dialog>(null);
  const [jobDetail, setJobDetail] = useState<Job | null>(null);
  const [search, setSearch] = useState("");
  const [sourceFilter, setSourceFilter] = useState("全部来源");
  const [hotFilter, setHotFilter] = useState("全部账号");
  const [subtitleTab, setSubtitleTab] = useState("人物构图");
  const [prefs, setPrefs] = useState<Prefs | null>(null);
  const [tikhubKey, setTikhubKey] = useState("");
  const [asrKey, setAsrKey] = useState("");
  const [accountInput, setAccountInput] = useState("");
  const [accountName, setAccountName] = useState("");
  const [accountGroup, setAccountGroup] = useState("默认分组");
  const [rule, setRule] = useState<Partial<Rule>>(ruleDefaults);
  const [ruleId, setRuleId] = useState("");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [supplement, setSupplement] = useState<Supplement | null>(null);
  const [registering, setRegistering] = useState(false);
  const pageRef = useRef<HTMLDivElement>(null);
  const activeRef = useRef<{ id: string; route: Route }>({ id: "", route });
  const outputDirty = useRef(false);
  const mounted = useRef(true);
  const selected = work?.segments.find(segment => segment.id === selectedId) ?? work?.segments[0];
  const pending = work?.segments.filter(segment => segment.status !== "exact" && !segment.accepted) ?? [];
  const ready = work ? workReady(work) : false;
  const authenticated = !state?.auth.required && !!state?.auth.user;
  const pro = state?.auth.user?.tier === "pro";
  const basics = useBasics(authenticated, route, notify);
  const finished = state?.jobs.filter(job => job.status === "done") ?? [];

  function navigate(next: Route) { setRoute(next); location.hash = `/${next}`; setSearch(""); }
  function notify(message: string) { setToast(message); }
  async function refresh(): Promise<void> {
    try {
      const value = await request<AppState>("/smart/state");
      if (!mounted.current) return;
      setState(value); setError("");
      setPrefs(previous => previous ?? value.settings);
      if (activeRef.current.id && STAGES.includes(activeRef.current.route) && !value.auth.required && value.auth.user?.tier === "pro") {
        const current = await request<Work>(`/smart/works/${activeRef.current.id}`);
        if (!mounted.current || current.id !== activeRef.current.id) return;
        setWork(current);
        if (!outputDirty.current) setOutput(current.settings);
      }
    } catch (failure) { if (mounted.current) setError((failure as Error).message); }
  }
  async function act<T>(operation: () => Promise<T>, message = ""): Promise<T | null> {
    setBusy(true);
    try { const result = await operation(); if (message) notify(message); await refresh(); return result; }
    catch (failure) { notify((failure as Error).message); return null; }
    finally { setBusy(false); }
  }
  useEffect(() => {
    mounted.current = true; void refresh();
    const listener = () => setRoute(routeFromHash()); window.addEventListener("hashchange", listener);
    const timer = setInterval(() => { void refresh(); }, 2000);
    return () => { mounted.current = false; clearInterval(timer); window.removeEventListener("hashchange", listener); };
  }, []);
  useEffect(() => { activeRef.current.route = route; pageRef.current?.scrollTo({ top: 0 }); if (route === "settings" && state) setPrefs(state.settings); }, [route]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(""), 5000); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => {
    if (!authenticated || !state?.settings.library_root || !["create", "rules", "settings"].includes(route)) return;
    void request<Array<{ name: string; count: number }>>("/smart/library/folders").then(setFolders).catch(() => setFolders([]));
  }, [authenticated, route, state?.settings.library_root]);

  useEffect(() => { if (!authenticated || !pro) { setDialog(null); setJobDetail(null); setWork(null); setSupplement(null); activeRef.current.id = ""; } }, [authenticated, pro]);
  async function openWork(workId: string, stage?: Route): Promise<void> {
    const current = await act(() => request<Work>(`/smart/works/${workId}`)); if (!current) return;
    activeRef.current.id = current.id; setWork(current); setInputScript(current.script); setOutput(current.settings); outputDirty.current = false;
    setSelectedId(current.segments.find(segment => segment.status !== "exact" && !segment.accepted)?.id ?? current.segments[0]?.id ?? 1);
    navigate(stage ?? (current.segments.length ? "review" : "create"));
  }
  function newWork() {
    activeRef.current.id = ""; setWork(null); setInputScript(""); setOutput({ ...DEFAULT_OUTPUT, source_folder: state?.settings.default_source_folder ?? "" }); outputDirty.current = false; navigate("create");
  }
  async function generate() {
    await act(async () => {
      let current = work;
      if (!current) current = await request<Work>("/smart/works", "POST", { script: inputScript });
      else current = await request<Work>(`/smart/works/${current.id}`, "PATCH", { script: inputScript, settings: output });
      if (!work) current = await request<Work>(`/smart/works/${current.id}`, "PATCH", { settings: output });
      activeRef.current.id = current.id; setWork(current); setSelectedId(1); outputDirty.current = false;
      await request(`/smart/works/${current.id}/plan`, "POST", {}); navigate("review");
    });
  }
  async function saveOutput(): Promise<Work | null> {
    if (!work) return null;
    if (!outputDirty.current) return work;
    const saved = await request<Work>(`/smart/works/${work.id}`, "PATCH", { settings: output });
    outputDirty.current = false; setWork(saved); return saved;
  }
  async function render() {
    await act(async () => { const saved = await saveOutput(); if (!saved) return; await request(`/smart/works/${saved.id}/render`, "POST", {}); navigate("tasks"); }, "已提交本机任务，结果会保存到智能工作区");
  }
  async function selectCandidate(candidateId: string) {
    if (!work || !selected) return;
    const saved = await act(() => request<Work>(`/smart/works/${work.id}/segments/${selected.id}`, "PATCH", { revision: work.revision, candidate_id: candidateId }));
    if (saved) setWork(saved);
  }
  async function acceptNear() {
    if (!work || !selected) return;
    const saved = await act(() => request<Work>(`/smart/works/${work.id}/segments/${selected.id}`, "PATCH", { revision: work.revision, accepted: true }));
    if (saved) setWork(saved);
  }
  async function showJob(jobId: string, film = false) {
    const result = await act(() => request<Job>(`/smart/jobs/${jobId}`)); if (result) { setJobDetail(result); setDialog({ kind: film ? "film" : "job", id: jobId }); }
  }
  function editOutput<K extends keyof OutputSettings>(field: K, value: OutputSettings[K]) { outputDirty.current = true; setOutput(previous => ({ ...previous, [field]: value })); }
  function backToMode() { navigate(work?.origin.trigger === "automatic" ? "automatic" : "home"); }
  function sourceFolder(value: string, onChange: (value: string) => void) { return <select aria-label="素材范围" value={value} onChange={event => onChange(event.target.value)}><option value="">全部已发布素材</option>{folders.map(folder => <option key={folder.name} value={folder.name}>{folder.name} · {folder.count} 条</option>)}</select>; }
  function modeTabs() { return <div className="creation-modes" role="tablist" aria-label="创作模式"><button role="tab" aria-selected={!AUTO.includes(route)} className={!AUTO.includes(route) ? "active" : ""} onClick={() => navigate("home")}><IconSparkles size={19} /><span><strong>手动创作</strong><small>由我发起，输入或选择文案</small></span></button><button role="tab" aria-selected={AUTO.includes(route)} className={AUTO.includes(route) ? "active" : ""} onClick={() => navigate("automatic")}><IconAutomation size={19} /><span><strong>自动创作</strong><small>由规则发起，持续生成作品</small></span></button></div>; }
  function autoNav() { return <nav className="auto-nav" aria-label="自动创作导航">{(["automatic", "monitor", "hot", "rules"] as Route[]).map(key => <button key={key} className={route === key ? "active" : ""} onClick={() => navigate(key)}>{key === "automatic" ? "运行工作台" : NAMES[key]}</button>)}</nav>; }
  function originBar() { return <div className="origin-bar"><Origin origin={work?.origin ?? { trigger: "manual", kind: "manual_script" }} /><span className="grow" /><button className="text-btn" onClick={backToMode}>{work?.origin.trigger === "automatic" ? "返回自动工作台" : "返回我的作品"}<IconArrowRight size={13} /></button></div>; }
  function workBadge(item: WorkSummary) { return <Badge tone={item.status === "done" || item.status === "ready" ? "green" : item.status === "failed" || item.pending_count ? "amber" : "blue"}>{item.pending_count && item.status !== "matching" ? `${item.pending_count} 句待审核` : WORK_NAMES[item.status]}</Badge>; }

  function manualPage() {
    const works = state?.works.filter(item => item.origin.trigger === "manual") ?? [];
    return <><Header title="手动创作" subtitle="由你发起：输入整段文案，或者选择一条热点文案开始。"><Button variant="primary" icon={IconPlus} onClick={newWork}>新建作品</Button></Header>
      <div className="start-block"><section className="start-card primary-start"><IconSparkles size={23} stroke={1.5} color="#4179dc" /><h2>输入文案，生成原声视频</h2><p>作品自动命名和拆句，查找素材实际说出的原声。确认后在本机完成构图、字幕和导出。</p><div className="mini-flow"><span>输入文案</span><IconChevronRight size={12} /><span>确认原声</span><IconChevronRight size={12} /><span>本机成片</span></div><Button variant="primary" icon={IconArrowRight} onClick={newWork}>开始创作</Button></section><section className="start-card"><IconTrendingUp size={23} stroke={1.5} color="#6583ad" /><h2>手动挑选热点文案</h2><p>从关注账号的真实热点中挑选参考文案，再由你点击创作。发起方式仍为手动。</p><div className="row" style={{ margin: "18px 0" }}><Badge tone="blue">{state?.hot.length ?? 0} 条近期候选</Badge><Badge>手动发起</Badge></div><Button icon={IconArrowRight} onClick={() => navigate("hot")}>挑选热点文案</Button></section></div>
      <div className="row between" style={{ marginBottom: 13 }}><h2>我的手动作品</h2><span className="small muted">最近 100 条作品 · 输出保存在本机</span></div><div className="panel">{!works.length ? <Empty>还没有手动作品，输入一段文案开始创作</Empty> : <table className="table"><thead><tr><th>作品</th><th>当前进度</th><th>文案来源</th><th>更新</th><th>操作</th></tr></thead><tbody>{works.filter(item => item.title.includes(search)).map(item => <tr key={item.id}><td><div className="name">{item.title}</div><div className="sub">{item.segment_count} 句 · {item.settings.ratio} · 原声</div></td><td>{workBadge(item)}</td><td><Badge>{originName(item.origin)}</Badge>{item.origin.account_name && <div className="sub">{item.origin.account_name}</div>}</td><td className="muted">{dateText(item.updated_at)}</td><td><Button small onClick={() => void openWork(item.id)}>{item.segment_count ? "继续审核" : "继续编辑"}</Button></td></tr>)}</tbody></table>}</div></>;
  }
  function createPage() {
    return <><Header title="输入文案" subtitle="只需输入整段文案，作品自动命名并拆句匹配。" />{originBar()}<Steps active={0} /><div className="form-grid"><section className="panel"><div className="panel-head"><h2>整段文案</h2><Badge tone="blue">素材原声</Badge></div><div className="panel-pad"><div className="form-group"><label htmlFor="script">输入文案</label><textarea id="script" className="script-input" value={inputScript} onChange={event => setInputScript(event.target.value)} placeholder="粘贴整段文案，无需起名，也不用手动拆句。" /><div className="row between small muted" style={{ marginTop: 8 }}><span>{Array.from(inputScript).length} 字 · 自动拆句</span><span>缺句会明确标记</span></div></div><details className="optional-settings"><summary>可选设置 · 使用默认配置即可开始</summary><div className="form-group" style={{ marginTop: 16 }}><label>优先素材范围</label>{sourceFolder(output.source_folder, value => editOutput("source_folder", value))}</div><div className="form-group"><label htmlFor="input-ratio">画面比例</label><select id="input-ratio" value={output.ratio} onChange={event => editOutput("ratio", event.target.value as OutputSettings["ratio"])}><option value="9:16">竖屏 9:16</option><option value="16:9">横屏 16:9</option></select></div></details><Banner>素材原声必须真实覆盖文案。近似表达需确认，关键缺句不会被自动省略。</Banner></div><div className="panel-foot row between"><span className="small muted">生成后进入本作品的匹配审核</span><Button variant="primary" icon={IconSparkles} disabled={busy || !inputScript.trim()} onClick={() => void generate()}>{busy ? "正在提交…" : "生成匹配方案"}</Button></div></section><aside className="stack"><div className="panel"><div className="panel-head"><h2>作品信息</h2><Badge tone="blue">自动命名</Badge></div><div className="panel-pad"><span className="small muted">自动名称</span><p className="automatic-name">{automaticTitle(inputScript) || "输入文案后自动生成"}</p><p className="small muted">根据首句生成简短名称，无需填写。</p>{[["素材范围", output.source_folder || "全部已发布素材"], ["画面比例", output.ratio], ["声音", "素材原声"], ["人物", "跟随主讲人"], ["字幕", "实际原声文案"], ["输出", "本机 MP4 + SRT"]].map(([label, value]) => <div className="scope-line" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div></div><div className="panel panel-pad"><h3>一条作品，完整走完四步</h3><div className="check-line"><IconCheck size={15} />输入、审核和调整属于同一作品</div><div className="check-line"><IconCheck size={15} />匹配使用已发布的真实素材</div><div className="check-line"><IconCheck size={15} />结果与来源记录保存在本机</div></div></aside></div></>;
  }
  function reviewPage() {
    if (!work) return <Empty>请从作品列表打开一条作品</Empty>;
    return <><Header title="匹配审核" subtitle={`${work.title} · 对照目标文案与实际原声。`}><Button icon={IconArrowLeft} onClick={() => { setInputScript(work.script); navigate("create"); }}>修改文案</Button><Button variant="primary" icon={IconArrowRight} disabled={!work.segments.length} onClick={() => navigate("preview")}>成片调整</Button></Header>{originBar()}<Steps active={1} />
      {work.status === "matching" ? <div className="panel empty"><IconRefresh size={25} /><p>正在检索真实原声片段…</p><p className="module-note">素材快照首次同步或长文案匹配可能需要时间。</p></div> : !work.segments.length ? <><Banner tone="amber">{work.error || "该作品尚未生成匹配方案"}</Banner><Button variant="primary" style={{ marginTop: 15 }} onClick={() => { setInputScript(work.script); navigate("create"); }}>回到文案生成方案</Button></> : <>
      <div className="review-summary"><strong>{work.segments.length} 句</strong><span className="muted">预计 {duration(work.segments.reduce((sum, segment) => sum + (segment.selected ? segment.selected.end_ms - segment.selected.begin_ms : 0), 0))}</span><Badge tone="green">{work.segments.filter(segment => segment.status === "exact").length} 句原文</Badge><Badge tone="amber">{work.segments.filter(segment => segment.status === "near").length} 句近似</Badge><Badge tone="red">{work.segments.filter(segment => segment.status === "gap" || segment.status === "conflict").length} 句需处理</Badge><span className="grow" /><span className="muted">{pending.length ? `${pending.length} 句待确认` : "原声内容已就绪"}</span></div>
      <div className="review-grid"><section><div className="sentence-list">{work.segments.map(segment => <article className={`sentence ${selected?.id === segment.id ? "selected" : ""}`} key={segment.id} role="button" tabIndex={0} aria-label={`审核第${segment.id}句`} onClick={() => setSelectedId(segment.id)} onKeyDown={event => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setSelectedId(segment.id); } }}><div className="sentence-header"><span className="sentence-id"><b>{String(segment.id).padStart(2, "0")}</b>{segment.id === 1 ? "开场" : segment.id === work.segments.length ? "收尾" : "正文"}</span><MatchBadge status={segment.status} accepted={segment.accepted} /></div><div className="sentence-pair"><div><div className="sentence-label">目标文案</div><div className="sentence-text">{segment.target}</div></div><div><div className="sentence-label">实际原声</div><div className={`sentence-text sentence-actual ${segment.status === "near" ? "diff" : ""}`}>{segment.actual || <span className="muted">尚未找到可用片段</span>}</div></div></div><div className="sentence-meta"><span>{segment.selected?.source_title || "暂无来源"}</span><span>{segment.selected ? `${duration(segment.selected.begin_ms)} – ${duration(segment.selected.end_ms)}` : "—"}<IconChevronRight size={10} /></span></div></article>)}</div></section>
      <aside className="inspector stack"><div className="panel"><SourcePlayer workId={work.id} segmentId={selected?.id ?? 1} candidate={selected?.selected ?? null} /><div className="source-detail"><div className="row between"><h3>{selected?.selected?.source_title || "等待补选片段"}</h3>{selected && <MatchBadge status={selected.status} accepted={selected.accepted} />}</div><p style={{ marginTop: 9 }}>{selected?.status === "exact" ? "文案与素材转写一致，请留意声音边界。" : selected?.status === "conflict" ? "数字或否定表述存在冲突，请修改目标文案或更换片段。" : selected?.status === "near" ? "请试听并核对数字、实体和含义，再接受实际原声。" : "可以扩大查询或回到文案修改这一句。"}</p>{selected?.status === "near" && <Button small variant="soft" icon={IconCheck} disabled={busy || selected.accepted} onClick={() => void acceptNear()} style={{ marginTop: 12 }}>{selected.accepted ? "这句原声已确认" : "接受这句实际原声"}</Button>}</div><div className="panel-head"><h3>替代候选</h3><button className="text-btn" onClick={() => { if (!work || !selected) return; setSupplement({ workId: work.id, segmentId: selected.id, revision: work.revision, target: selected.target }); basics.setScope("public"); basics.setQuery(selected.target); navigate("retrieve"); }}>手动补选</button></div>{selected?.candidates.map(candidate => <div className="candidate" key={candidate.id}><div className="candidate-icon"><IconMovie size={22} /></div><div className="grow"><strong>{candidate.source_title}</strong><p>{candidate.lecturer || "无讲师标签"} · {duration(candidate.begin_ms)} – {duration(candidate.end_ms)}</p><p className="candidate-words">{candidate.actual}</p></div><Button small disabled={busy || selected.selected?.id === candidate.id} onClick={() => void selectCandidate(candidate.id)}>使用</Button></div>)}{!selected?.candidates.length && <div className="panel-pad"><p className="small muted">没有自动可用片段。</p><Button small variant="soft" icon={IconPlus} style={{ marginTop: 12 }} onClick={() => { if (!work || !selected) return; setSupplement({ workId: work.id, segmentId: selected.id, revision: work.revision, target: selected.target }); basics.setScope("public"); basics.setQuery(selected.target); navigate("retrieve"); }}>手动补选片段</Button></div>}</div></aside></div></>}
    </>;
  }
  function previewPage() {
    if (!work) return <Empty>请先打开作品</Empty>;
    const candidate = selected?.selected ?? null;
    return <><Header title="成片调整" subtitle={`${work.title} · 检查画面、原声和字幕。`}><Button icon={IconArrowLeft} onClick={() => navigate("review")}>返回审核</Button><Button variant="primary" icon={IconMovie} disabled={busy || !ready || !state?.settings.runtime.ffmpeg_ready} onClick={() => void render()}>开始本机导出</Button></Header>{originBar()}<Steps active={2} />{(!ready || work.error) && <><Banner tone="amber">{work.error || `仍有 ${pending.length} 句需处理，请完成原声审核后导出。`}</Banner><div className="space" /></>}
      <div className="preview-grid"><div className="panel"><div className="panel-head"><h3>成片预览</h3><Badge tone="blue">{output.ratio} · 原声</Badge></div><div className="preview-stage"><div className={`portrait-frame ${output.ratio === "16:9" ? "landscape" : ""}`} style={{ "--crop-position": `${output.crop_position * 100}%` } as React.CSSProperties}><SourcePlayer workId={work.id} segmentId={selected?.id ?? 1} candidate={candidate} className={output.crop_mode === "fit" ? "fit-preview" : "crop-preview"} />{output.subtitles && candidate && <div className={`preview-subtitle ${output.subtitle_style === "yellow" ? "yellow" : ""}`} style={{ fontSize: Math.max(12, Math.round(output.subtitle_size * 0.23)) }}>{candidate.actual}</div>}</div><span className="stage-label">{output.crop_mode === "follow" ? "本机导出时检测主讲人；歧义会进入待确认" : output.crop_mode === "fit" ? "保留全景" : "手动取景"}</span></div><div className="timeline-clips">{work.segments.map(segment => <button className={`timeline-clip ${selected?.id === segment.id ? "active" : ""}`} key={segment.id} onClick={() => setSelectedId(segment.id)}><span>片段 {segment.id}</span><small>{segment.selected ? duration(segment.selected.end_ms - segment.selected.begin_ms) : "缺少片段"}</small></button>)}</div></div>
      <aside className="stack"><div className="panel"><div className="panel-head"><h3>成片设定</h3><Button small disabled={!outputDirty.current || busy} onClick={() => void act(saveOutput, "成片设定已保存")}>保存设定</Button></div><div className="tabs preview-tabs">{["人物构图", "字幕", "声音"].map(label => <button className={subtitleTab === label ? "active" : ""} key={label} onClick={() => setSubtitleTab(label)}>{label}</button>)}</div><div className="panel-pad">{subtitleTab === "人物构图" ? <><div className="form-group"><label htmlFor="crop">取景方式</label><select id="crop" value={output.crop_mode} onChange={event => editOutput("crop_mode", event.target.value as OutputSettings["crop_mode"])}><option value="follow">跟随主讲人</option><option value="center">手动居中</option><option value="fit">保留全景</option></select></div><div className="form-group"><label htmlFor="position">横向构图 · {Math.round(output.crop_position * 100)}%</label><input id="position" type="range" min="0" max="1" step="0.01" value={output.crop_position} disabled={output.crop_mode !== "center"} onChange={event => editOutput("crop_position", Number(event.target.value))} /></div><p className="module-note">无法安全确定人物时，可保留全景或手动调整。</p></> : subtitleTab === "字幕" ? <><div className="scope-line"><span>烧录字幕</span><Switch label="烧录字幕" checked={output.subtitles} onChange={value => editOutput("subtitles", value)} /></div><div className="form-group"><label htmlFor="subtitle-style">字幕样式</label><select id="subtitle-style" value={output.subtitle_style} onChange={event => editOutput("subtitle_style", event.target.value as OutputSettings["subtitle_style"])}><option value="white">清晰白字</option><option value="yellow">醒目黄字</option></select></div><div className="form-group"><label htmlFor="subtitle-size">成片字号 · {output.subtitle_size}</label><input id="subtitle-size" type="range" min="24" max="100" value={output.subtitle_size} onChange={event => editOutput("subtitle_size", Number(event.target.value))} /></div><p className="module-note">字幕按最终实际原声和时间线生成，同时保存 SRT。</p></> : <><div className="scope-line"><span>保留素材原声</span><Badge tone="green">已启用</Badge></div><div className="scope-line"><span>统一响度</span><Switch label="统一响度" checked={output.normalize_audio} onChange={value => editOutput("normalize_audio", value)} /></div><div className="scope-line"><span>限制同讲师</span><Switch label="限制同讲师" checked={output.same_lecturer} onChange={value => editOutput("same_lecturer", value)} /></div><p className="module-note">跨讲师可能产生声音与画面跳变，请试听确认。</p></>}</div></div><div className="panel panel-pad"><h3>输出到本机</h3><div className="path" style={{ margin: "12px 0" }}>{state?.settings.workspace_root}</div><div className="scope-line"><span>格式</span><strong>MP4 · H.264 + AAC</strong></div><div className="scope-line"><span>附带文件</span><strong>SRT · 来源记录</strong></div></div></aside></div></>;
  }
  function automaticPage() {
    const works = state?.works.filter(item => item.origin.trigger === "automatic") ?? [];
    const enabled = state?.rules.filter(item => item.enabled) ?? [];
    const monitor = state?.monitor;
    const status = monitor?.running ? "正在检查" : !state?.settings.has_tikhub_key ? "等待 API 配置" : !state.accounts.some(account => account.enabled) ? "等待关注账号" : enabled.length ? "规则已启用" : "规则已暂停";
    return <><Header title="自动创作" subtitle="由规则发起：监控抖音账号，获取真实口播文案，再按约定条件成片。"><Button icon={IconSettings} onClick={() => navigate("rules")}>配置规则</Button><Button variant="primary" icon={IconRefresh} disabled={busy || !!monitor?.running || !state?.settings.has_tikhub_key} onClick={() => void act(() => request("/smart/monitor/run", "POST", {}), "已开始检查，进度和异常会显示在工作台")}>立即检查一次</Button></Header>
      <div className="automation-stats"><div><span>当前状态</span><strong>{status}</strong><small>{enabled.length} 条启用规则</small></div><div><span>监控账号</span><strong>{state?.accounts.filter(account => account.enabled).length ?? 0}<em> 个</em></strong><small>抖音</small></div><div><span>待处理作品</span><strong>{works.filter(item => item.status === "review" || item.status === "failed").length}<em> 条</em></strong><small>缺句、近似或构图需确认</small></div><div><span>自动成片</span><strong>{finished.filter(job => job.origin.trigger === "automatic").length}<em> 条</em></strong><small>本机真实输出</small></div></div>
      <section className="panel auto-rule-summary"><div className="row between"><div><h3>{enabled.length ? enabled.map(item => item.name).join("、") : "配置一条规则开始自动创作"}</h3><p className="small muted">应用运行时按设定周期检查，退出后保存本机任务检查点。</p></div><Button small onClick={() => navigate("rules")}>管理规则</Button></div><div className="auto-pipeline">{["监控账号", "筛选视频", "下载与提取口播", "匹配原声", "审核 / 自动通过", "本机成片"].map((label, index) => <React.Fragment key={label}><span>{label}</span>{index < 5 && <IconChevronRight size={12} />}</React.Fragment>)}</div><div className="row between small muted"><span>最近检查：{dateText(String(monitor?.finished_at || ""))}</span><span>{monitor?.running ? String(monitor.phase) : `今日接口请求 ${state?.request_count ?? 0} / ${state?.settings.request_limit_per_day ?? 0}`}</span></div>{!!monitor?.error && <div className="module-note error-note">{String(monitor.error)}</div>}</section>
      {!!state?.rules.some(item => item.last_error) && <><Banner tone="amber">{state.rules.find(item => item.last_error)?.last_error}</Banner><div className="space" /></>}
      <div className="row between auto-results-head"><h2>规则产生的作品与任务</h2><button className="text-btn" onClick={() => navigate("tasks")}>全部本机任务<IconArrowRight size={13} /></button></div><div className="panel">{!works.length ? <Empty>还没有自动作品，先添加关注账号并启用规则</Empty> : <table className="table auto-results"><thead><tr><th>自动作品</th><th>来源账号 / 规则</th><th>状态与原因</th><th>操作</th></tr></thead><tbody>{works.map(item => <tr key={item.id}><td><div className="name">{item.title}</div><div className="sub">{dateText(item.created_at)}</div></td><td><div>{item.origin.account_name}</div><div className="sub">{item.origin.rule_name}</div></td><td>{workBadge(item)}<div className="sub">{item.error || (item.pending_count ? "原声内容需人工处理" : item.status === "done" ? "结果已保存在本机" : "等待审核或本机执行")}</div></td><td><Button small onClick={() => void openWork(item.id)}>查看作品</Button></td></tr>)}</tbody></table>}</div></>;
  }
  function filmsPage() {
    const jobs = finished.filter(job => job.title.includes(search) && (sourceFilter === "全部来源" || modeName(job.origin) === sourceFilter));
    const assemblies = state?.assemblies.filter(job => job.status === "done" && job.title.includes(search) && sourceFilter !== "自动创作") ?? [];
    const clips = basics.locals.clips.filter(clip => `${clip.title}${clip.selected_text}`.includes(search) && sourceFilter !== "自动创作");
    return <><Header title="本地成果" subtitle="本机保存的剪切片段、完整视频与来源记录。"><Button icon={IconFolderOpen} onClick={() => void act(() => request("/smart/workspace/open", "POST", {}))}>打开本机工作区</Button></Header><div className="filterbar"><input placeholder="搜索成片名称" value={search} onChange={event => setSearch(event.target.value)} /><select aria-label="成片来源" value={sourceFilter} onChange={event => setSourceFilter(event.target.value)}><option>全部来源</option><option>手动创作</option><option>自动创作</option></select><span className="grow" /><span className="small muted">{jobs.length + assemblies.length + clips.length} 条已加载成果</span></div><div className="film-grid">{assemblies.map(job => <article className="panel film-card" key={job.id}><div className="real-media"><video controls preload="metadata" src={mediaUrl(`/smart/assemblies/${job.id}/video`)} /></div><div className="film-body"><h3>{job.title}</h3><p>{duration(job.duration_ms)} · {job.cut_job_ids.length} 段按顺序合并</p><Badge>检索合并 · 素材原声</Badge></div><div className="film-footer"><button className="text-btn" onClick={() => void act(() => request(`/smart/assemblies/${job.id}/open`, "POST", {}))}>打开目录</button><a className="text-btn" href={mediaUrl(`/smart/assemblies/${job.id}/srt`)} download="subtitles.srt">字幕</a><a className="text-btn" href={mediaUrl(`/smart/assemblies/${job.id}/manifest`)} download="sources.json">来源记录</a></div></article>)}{clips.map(clip => <article className="panel film-card" key={clip.local_clip_id}><div className="real-media"><video controls preload="metadata" src={clip.media_url} poster={clip.cover_url} /></div><div className="film-body"><h3>{clip.title}</h3><p>{clip.selected_text}</p><Badge>检索剪切 · {duration(clip.duration_ms ?? 0)}</Badge></div><div className="film-footer"><Button small onClick={() => void basics.act(async () => { await basics.choose(clip.local_clip_id, "local"); basics.setScope("local"); navigate("retrieve"); })}>继续拖选</Button></div></article>)}{jobs.map(job => <article className="panel film-card" key={job.id}><div className="real-media"><video preload="metadata" controls src={mediaUrl(`/smart/media/jobs/${job.id}/video`)} /></div><div className="film-body"><h3>{job.title}</h3><p>{duration(job.duration_ms)} · {job.ratio} · 素材原声</p><div className="job-source"><Origin origin={job.origin} /></div></div><div className="film-footer"><button className="text-btn" onClick={() => void showJob(job.id, true)}><IconEye size={13} />预览与来源</button><button className="text-btn" onClick={() => void act(() => request(`/smart/jobs/${job.id}/open`, "POST", {}))}><IconFolderOpen size={13} />打开目录</button></div></article>)}</div>{!jobs.length && !clips.length && !assemblies.length && <div className="panel"><Empty>完成本机导出后，成片会出现在这里</Empty></div>}</>;
  }
  function monitorPage() {
    const accounts = state?.accounts.filter(account => account.name.includes(search)) ?? [];
    return <><Header title="博主监控" subtitle="关注真实抖音账号，按设定间隔增量检查并记录热度。"><Button variant="primary" icon={IconPlus} disabled={busy || !state?.settings.has_tikhub_key} onClick={() => { setAccountInput(""); setAccountName(""); setAccountGroup("默认分组"); setDialog({ kind: "account" }); }}>添加关注账号</Button></Header>{!state?.settings.has_tikhub_key && <><Banner tone="amber">请先在设置配置 TikHub API Key。<button className="text-btn" onClick={() => navigate("settings")}>去配置</button></Banner><div className="space" /></>}<div className="filterbar"><input placeholder="搜索关注账号" value={search} onChange={event => setSearch(event.target.value)} /><span className="grow" /><Badge tone="blue">每 {state?.settings.monitor_interval_minutes ?? 30} 分钟检查</Badge><Button small icon={IconRefresh} disabled={busy || !!state?.monitor?.running} onClick={() => void act(() => request("/smart/monitor/run", "POST", {}))}>立即检查</Button></div><div className="panel">{!accounts.length ? <Empty>添加抖音主页链接，开始关注账号动态</Empty> : <table className="table"><thead><tr><th>账号</th><th>分组</th><th>粉丝</th><th>最近检查 / 异常</th><th>监控</th><th>候选</th></tr></thead><tbody>{accounts.map(account => <tr key={account.id}><td><div className="name">{account.name}</div><div className="sub">抖音 · {account.unique_id || account.sec_user_id.slice(0, 20)}</div></td><td>{account.group}</td><td>{numberText(account.followers)}</td><td><div className="muted">{dateText(account.last_checked_at)}</div>{account.last_error && <div className="sub error-note">{account.last_error}</div>}</td><td><Switch label={`监控${account.name}`} checked={account.enabled} disabled={busy} onChange={enabled => void act(() => request(`/smart/accounts/${account.id}`, "PATCH", { enabled }))} /></td><td><button className="text-btn" onClick={() => { setHotFilter(account.id); navigate("hot"); }}>查看热点</button></td></tr>)}</tbody></table>}</div></>;
  }
  function hotPage() {
    const videos = state?.hot.filter(item => hotFilter === "全部账号" || item.account_id === hotFilter).filter(item => item.title.includes(search)) ?? [];
    return <><Header title="热点文案" subtitle="共享热点参考池：手动选用属于手动创作，规则触发属于自动创作。"><Button icon={IconRefresh} disabled={busy || !!state?.monitor?.running} onClick={() => void act(() => request("/smart/monitor/run", "POST", {}))}>刷新热点</Button></Header><div className="filterbar"><select aria-label="热点账号筛选" value={hotFilter} onChange={event => setHotFilter(event.target.value)}><option>全部账号</option>{state?.accounts.map(account => <option key={account.id} value={account.id}>{account.name}</option>)}</select><input placeholder="搜索热点内容" value={search} onChange={event => setSearch(event.target.value)} /><span className="grow" /><span className="small muted">增长需要前后两次有效观测</span></div><div className="hot-grid">{videos.map(item => <article className="panel" key={item.id}><div className="hot-cover">{item.cover_url ? <img src={item.cover_url} alt={`${item.title}封面`} /> : <IconMovie size={35} stroke={1.3} />}<Badge tone="blue">抖音</Badge></div><div className="hot-info"><h3>{item.title || "无标题视频"}</h3><p>{item.author} · {dateText(item.published_at)}</p><div className="hot-metrics"><div><strong>{numberText(item.observations.at(-1)?.stats.likes)}</strong><span>累计点赞</span></div><div><strong style={{ fontSize: 12 }}>{item.growth_per_hour === null ? "待观测" : `+${Math.round(item.growth_per_hour).toLocaleString()} / 小时`}</strong><span>近期增长</span></div></div><div className="row between"><Badge tone={item.status === "ready" ? "green" : item.status === "failed" ? "amber" : "blue"}>{item.status === "ready" ? "口播已提取" : item.status === "failed" ? "需处理" : item.status === "downloading" ? "下载中" : item.status === "transcribing" ? "转写中" : "待提取"}</Badge><span className="small muted">播放 {numberText(item.observations.at(-1)?.stats.plays)}</span></div><div className="hot-foot"><span className="small muted">{duration(item.duration_ms)}</span><Button small onClick={() => setDialog({ kind: "hot", id: item.id })}>查看文案</Button></div></div></article>)}</div>{!videos.length && <div className="panel"><Empty>当前没有热点候选，添加账号并检查后会显示真实作品</Empty></div>}<div className="space" /><Banner>作品标题不等于口播文案。需要提取视频实际声音，之后仍要检查自有素材是否覆盖。</Banner></>;
  }
  function rulesPage() {
    const pick = (value: string) => { setRuleId(value); setRule(value ? { ...state!.rules.find(item => item.id === value)! } : ruleDefaults()); };
    return <><Header title="自动化规则" subtitle="设置哪些内容进入创作，在哪一步需要人工介入。"><Button icon={IconPlus} onClick={() => pick("")}>新建规则</Button><Button variant="primary" icon={IconCheck} disabled={busy} onClick={() => void act(async () => { const saved = await request<Rule>(ruleId ? `/smart/rules/${ruleId}` : "/smart/rules", ruleId ? "PATCH" : "POST", rule); setRule(saved); setRuleId(saved.id); }, "规则已保存")}>保存规则</Button></Header><div className="filterbar"><select aria-label="选择规则" value={ruleId} onChange={event => pick(event.target.value)}><option value="">新建规则</option>{state?.rules.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select><span className="small muted">启用后才会按规则创建作品</span></div><div className="rule-grid"><section className="panel"><div className="panel-head"><h2>{rule.name}</h2><Switch label="启用自动化规则" checked={!!rule.enabled} onChange={enabled => setRule(previous => ({ ...previous, enabled }))} /></div><div className="rule-block"><h3><span className="rule-number">1</span>选择内容来源</h3><div className="rule-fields"><div><label htmlFor="rule-name">规则名称</label><input id="rule-name" value={rule.name ?? ""} onChange={event => setRule(previous => ({ ...previous, name: event.target.value }))} /></div><div><label htmlFor="rule-group">关注账号组</label><select id="rule-group" value={rule.account_group ?? ""} onChange={event => setRule(previous => ({ ...previous, account_group: event.target.value }))}><option value="">全部关注账号</option>{[...new Set(state?.accounts.map(account => account.group))].map(group => <option key={group}>{group}</option>)}</select></div></div></div><div className="rule-block"><h3><span className="rule-number">2</span>筛选热度候选</h3><div className="rule-fields"><div><label htmlFor="rule-age">发布于最近（小时）</label><input id="rule-age" type="number" min="1" max="720" value={rule.max_age_hours ?? 24} onChange={event => setRule(previous => ({ ...previous, max_age_hours: Number(event.target.value) }))} /></div><div><label htmlFor="rule-likes">最低累计点赞</label><input id="rule-likes" type="number" min="0" value={rule.min_likes ?? 1000} onChange={event => setRule(previous => ({ ...previous, min_likes: Number(event.target.value) }))} /></div><div><label htmlFor="rule-growth">最低增长 / 小时</label><input id="rule-growth" type="number" min="0" value={rule.min_growth_per_hour ?? 0} onChange={event => setRule(previous => ({ ...previous, min_growth_per_hour: Number(event.target.value) }))} /></div><div><label htmlFor="rule-candidates">每轮最多候选</label><input id="rule-candidates" type="number" min="1" max="10" value={rule.candidates_per_run ?? 2} onChange={event => setRule(previous => ({ ...previous, candidates_per_run: Number(event.target.value) }))} /></div></div><p className="module-note">增长阈值为 0 时只按点赞筛选；需要增长时，数据不足的作品不会自动通过。</p></div><div className="rule-block"><h3><span className="rule-number">3</span>匹配与审核</h3><div className="rule-fields"><div><label>自有素材范围</label>{sourceFolder(rule.source_folder ?? "", value => setRule(previous => ({ ...previous, source_folder: value })))}</div><div><label htmlFor="rule-execution">执行方式</label><select id="rule-execution" value={rule.execution ?? "review"} onChange={event => setRule(previous => ({ ...previous, execution: event.target.value as Rule["execution"] }))}><option value="plan">仅生成方案</option><option value="review">审核后导出</option><option value="qualified">条件满足自动导出</option></select></div></div><div className="space" /><Banner tone={rule.execution === "qualified" ? "amber" : ""}>{rule.execution === "qualified" ? "自动导出要求原文齐全、同讲师标签一致、人物构图通过。本机实际执行过程中发现歧义会进入待处理。" : "近似表达、缺句和构图歧义会进入人工审核。"}</Banner></div><div className="rule-block"><h3><span className="rule-number">4</span>本机输出与限额</h3><div className="rule-fields"><div><label htmlFor="rule-daily">每日自动处理上限</label><input id="rule-daily" type="number" min="1" max="100" value={rule.daily_limit ?? 5} onChange={event => setRule(previous => ({ ...previous, daily_limit: Number(event.target.value) }))} /></div><div><label>执行设备</label><p>{state?.device_name || "本机"}</p></div></div></div></section><aside className="stack"><div className="panel panel-pad"><h3>规则行为</h3><div className="scope-line"><span>平台</span><strong>抖音</strong></div><div className="scope-line"><span>声音</span><strong>素材原声</strong></div><div className="scope-line"><span>状态</span><Badge tone={rule.enabled ? "green" : ""}>{rule.enabled ? "保存后启用" : "暂停"}</Badge></div><p className="module-note">已处理参考视频不会因重复检查再次创建同一规则的作品。</p></div><div className="panel panel-pad"><h3>暂停规则</h3><p className="module-note">停止后续触发。已产生作品和本机任务保留，可在任务中心单独控制。</p></div></aside></div></>;
  }
  async function savePreferences() {
    if (!prefs) return;
    await act(async () => {
      const payload = { library_root: prefs.library_root, workspace_root: prefs.workspace_root, monitor_platform: prefs.monitor_platform,
        monitor_interval_minutes: prefs.monitor_interval_minutes, request_limit_per_day: prefs.request_limit_per_day,
        source_cache_gb: prefs.source_cache_gb, reference_cache_gb: prefs.reference_cache_gb, max_download_mb: prefs.max_download_mb,
        asr_model: prefs.asr_model, default_source_folder: prefs.default_source_folder,
        ...(tikhubKey.trim() ? { tikhub_api_key: tikhubKey.trim() } : {}), ...(asrKey.trim() ? { asr_api_key: asrKey.trim() } : {}) };
      const saved = await request<Prefs>("/smart/settings", "PUT", pro ? payload : { library_root: prefs.library_root, workspace_root: prefs.workspace_root, source_cache_gb: prefs.source_cache_gb });
      setPrefs(saved); setTikhubKey(""); setAsrKey("");
    }, "配置已保存，密钥不会回显");
  }
  async function chooseDirectory(field: "library_root" | "workspace_root") {
    if (!prefs) return;
    const selected = await pickDirectory(field === "library_root" ? "选择已发布公共素材库" : "选择智能剪辑本机工作区", prefs[field]);
    if (selected) setPrefs(previous => previous ? { ...previous, [field]: selected } : previous);
    else notify("桌面端可以选择文件夹；浏览器开发预览请填写绝对路径");
  }
  function settingsPage() {
    if (!prefs || !state) return <Empty>正在读取本机设置…</Empty>;
    return <UnifiedSettings state={state} prefs={prefs} setPrefs={setPrefs} pro={pro} busy={busy} authenticated={authenticated}
      tikhubKey={tikhubKey} setTikhubKey={setTikhubKey} asrKey={asrKey} setAsrKey={setAsrKey}
      save={savePreferences} choose={chooseDirectory} act={act} login={loginPage()} onCache={() => navigate("cache")} />;
  }
  function loginPage() {
    return <div className="login-panel panel"><h1>{registering ? "申请剪辑师账号" : "登录剪辑工作台"}</h1><p className="muted">使用管理端已审核的剪辑师账号，继续使用公共素材。</p><div className="form-group"><label htmlFor="login-user">用户名</label><input id="login-user" autoComplete="username" value={username} onChange={event => setUsername(event.target.value)} /></div><div className="form-group"><label htmlFor="login-pass">密码</label><input id="login-pass" type="password" autoComplete={registering ? "new-password" : "current-password"} value={password} onChange={event => setPassword(event.target.value)} /></div><div className="row between"><button className="text-btn" onClick={() => setRegistering(!registering)}>{registering ? "已有账号，去登录" : "没有账号，提交申请"}</button><Button variant="primary" disabled={busy || !username.trim() || !password} onClick={() => void act(async () => { await request(registering ? "/smart/auth/register" : "/smart/auth/login", "POST", { username, password }); setPassword(""); if (registering) notify("申请已提交，请等待管理端审核"); else notify("登录成功"); })}>{registering ? "提交申请" : "登录"}</Button></div><div className="space" /><button className="text-btn" onClick={() => navigate("settings")}>检查公共素材库和本机设置<IconArrowRight size={13} /></button></div>;
  }
  function dialogContent() {
    if (!dialog || !state) return null;
    const close = () => { setDialog(null); setJobDetail(null); };
    if (dialog.kind === "account") return <Modal title="添加抖音关注账号" onClose={close} footer={<><Button onClick={close}>取消</Button><Button variant="primary" disabled={busy || !accountInput.trim()} onClick={() => void act(async () => { await request("/smart/accounts", "POST", { platform: "douyin", input: accountInput, name: accountName, group: accountGroup }); close(); }, "真实账号已加入监控")}>{busy ? "正在解析…" : "添加账号"}</Button></>}><div className="form-group"><label htmlFor="account-input">主页链接或 sec_user_id</label><input id="account-input" value={accountInput} onChange={event => setAccountInput(event.target.value)} placeholder="https://www.douyin.com/user/..." /></div><div className="form-group"><label htmlFor="account-name">账号备注（可选）</label><input id="account-name" value={accountName} onChange={event => setAccountName(event.target.value)} placeholder="留空使用真实昵称" /></div><div className="form-group"><label htmlFor="account-group">分组</label><input id="account-group" value={accountGroup} onChange={event => setAccountGroup(event.target.value)} /></div><p className="module-note">添加时通过 TikHub 解析账号，计入请求配额。</p></Modal>;
    if (dialog.kind === "hot") {
      const hot = state.hot.find(item => item.id === dialog.id); if (!hot) return null;
      const processing = hot.status === "downloading" || hot.status === "transcribing";
      return <Modal title={hot.title || "热点参考视频"} onClose={close} wide footer={<><Button onClick={close}>关闭</Button>{hot.status === "ready" ? <Button variant="primary" icon={IconArrowRight} disabled={busy} onClick={() => void act(async () => { const imported = await request<Work>(`/smart/hot/${encodeURIComponent(hot.id)}/import`, "POST", {}); close(); await openWork(imported.id, "create"); })}>手动用此文案创作</Button> : <Button variant="primary" icon={IconFileText} disabled={busy || processing || !state.settings.has_asr_key} onClick={() => void act(() => request(`/smart/hot/${encodeURIComponent(hot.id)}/transcribe`, "POST", {}), "已开始实际下载和口播转写")}>{processing ? "正在处理…" : hot.status === "failed" ? "继续提取 / 查询任务" : "提取口播文案"}</Button>}</>}><div className="hot-detail-grid"><div><div className="hot-cover large">{hot.cover_url ? <img src={hot.cover_url} alt="真实视频封面" /> : <IconMovie size={40} />}</div><div className="detail-pairs"><div><label>账号</label><p>{hot.author}</p></div><div><label>发布时间</label><p>{dateText(hot.published_at)}</p></div><div><label>声音</label><p>参考视频实际口播</p></div><div><label>用途</label><p>参考文案，再匹配自己的素材</p></div></div></div><div><h3 style={{ marginBottom: 12 }}>{hot.status === "ready" ? "提取的口播文案" : processing ? "视频与口播处理中" : "文案待提取"}</h3>{hot.transcript ? <div className="script-block">{hot.transcript}</div> : <p className="muted">下载参考视频并识别实际声音，视频标题不会被当作口播。</p>}{hot.error && <><div className="space" /><Banner tone="amber">{hot.error}</Banner></>}{!state.settings.has_asr_key && <p className="module-note">需要先在设置配置语音转写 Key。</p>}{hot.status === "failed" && <Button small variant="danger" style={{ marginTop: 16 }} disabled={busy || processing} onClick={() => void act(() => request(`/smart/hot/${encodeURIComponent(hot.id)}/transcribe`, "POST", { force_resubmit: true }), "已明确创建新的转写任务")}>重新提交转写（新任务）</Button>}</div></div></Modal>;
    }
    if ((dialog.kind === "job" || dialog.kind === "film") && jobDetail) {
      const summary = state.jobs.find(item => item.id === jobDetail.id);
      const status = summary?.status ?? jobDetail.status;
      return <Modal title={dialog.kind === "film" ? "成片预览与来源" : "本机任务详情"} onClose={close} wide footer={<><Button onClick={close}>关闭</Button>{["queued", "running", "paused", "failed", "needs_review"].includes(status) && <Button variant="danger" onClick={() => void act(async () => { await request(`/smart/jobs/${jobDetail.id}/action`, "POST", { action: "cancel" }); close(); })}>取消任务</Button>}{status === "done" && <Button icon={IconFolderOpen} onClick={() => void act(() => request(`/smart/jobs/${jobDetail.id}/open`, "POST", {}))}>打开本地目录</Button>}</>}><h3>{jobDetail.work.title}</h3><div className="job-source"><Origin origin={jobDetail.work.origin} /></div>{dialog.kind === "film" && <div className="real-media"><video controls src={mediaUrl(`/smart/media/jobs/${jobDetail.id}/video`)} /></div>}<div className="detail-pairs"><div><label>状态</label><p>{JOB_NAMES[status]}</p></div><div><label>当前阶段</label><p>{summary?.phase ?? jobDetail.phase}</p></div><div><label>进度</label><p>{summary?.progress ?? jobDetail.progress}%</p></div><div><label>实际时长</label><p>{duration(jobDetail.duration_ms)}</p></div></div>{(summary?.error || jobDetail.error) && <Banner tone="amber">{summary?.error || jobDetail.error}</Banner>}<div className="path">{jobDetail.output_path}</div>{status === "done" && <div className="row" style={{ marginTop: 14 }}><a className="text-btn" href={mediaUrl(`/smart/media/jobs/${jobDetail.id}/srt`)} download="subtitles.srt">下载字幕 SRT<IconExternalLink size={13} /></a><a className="text-btn" href={mediaUrl(`/smart/media/jobs/${jobDetail.id}/manifest`)} download="sources.json">下载来源记录<IconExternalLink size={13} /></a></div>}<h3 style={{ margin: "20px 0 12px" }}>实际使用原声</h3><div className="script-block">{jobDetail.work.segments.map(segment => segment.actual).join("\n")}</div>{status === "needs_review" && <Button small style={{ marginTop: 14 }} onClick={() => { close(); void openWork(jobDetail.work_id, "preview"); }}>返回作品调整取景</Button>}</Modal>;
    }
    return null;
  }

  async function applySupplement(item: import("./basics.ts").CutListItemInput, range: import("./basics.ts").TextRange) {
    if (!supplement) return;
    const saved = await request<Work>(`/smart/works/${supplement.workId}/segments/${supplement.segmentId}/supplement`, "POST", {
      revision: supplement.revision, source_video_id: item.source_video_id, range, begin_ms: item.begin_ms, end_ms: item.end_ms
    });
    setWork(saved); setSelectedId(supplement.segmentId); setSupplement(null); navigate("review");
  }
  const smartRoutes: Route[] = ["home", ...AUTO, ...STAGES];
  const smartBlocked = authenticated && !pro && smartRoutes.includes(route);
  const automatic = AUTO.includes(route) || STAGES.includes(route) && work?.origin.trigger === "automatic";
  const page = { home: manualPage, automatic: automaticPage, create: createPage, review: reviewPage, preview: previewPage,
    retrieve: () => <Retrieval data={basics} pro={pro} supplement={supplement} onApply={applySupplement}
      onCancel={() => { setSupplement(null); navigate("review"); }} onSmart={script => { newWork(); setInputScript(script); }} onTasks={() => navigate("tasks")} />,
    projects: () => <Projects data={basics} smart={state?.works ?? []} pro={pro} onRetrieve={() => navigate("retrieve")} onCreate={newWork} onWork={id => void openWork(id)} />,
    local: () => <MaterialLibrary data={basics} kind="local" onRetrieve={() => { setSupplement(null); navigate("retrieve"); }} />,
    materials: () => <MaterialLibrary data={basics} kind="public" onRetrieve={() => { setSupplement(null); navigate("retrieve"); }} />,
    cache: () => <CacheManagement sourceLimit={state?.settings.source_cache_gb ?? 30} onLimit={async value => { await request("/smart/settings", "PUT", { source_cache_gb: value }); await refresh(); }} />,
    tasks: () => <Tasks data={basics} assemblies={state?.assemblies ?? []} smart={state?.jobs ?? []} onSmart={id => void showJob(id)} onLocal={() => navigate("local")} />,
    films: filmsPage, monitor: monitorPage, hot: hotPage, rules: rulesPage, settings: settingsPage }[route];
  return <div className="app production-app"><div className="body-layout"><aside className="sidebar"><div className="brand"><div className="brand-mark"><IconSparkles size={21} stroke={1.6} /></div><div><div className="brand-name">MixLab 剪辑工作台</div><div className="brand-sub">检索剪切 · 智能成片</div></div></div><nav aria-label="剪辑工作台导航">{[
      { group: "创作", items: [["retrieve", "文案检索", IconSearch], ...(pro ? [["home", "文案成片", IconSparkles]] : [])] },
      { group: "工作区", items: [["projects", "我的项目", IconFolder], ["tasks", "任务中心", IconListCheck], ["films", "本地成果", IconMovie]] },
      { group: "素材", items: [["local", "本地素材", IconBox], ["materials", "公共素材库", IconDatabase], ["cache", "缓存管理", IconRefresh]] }
    ].map(group => <React.Fragment key={group.group}><div className="nav-group">{group.group}</div>{group.items.map(([key, label, Icon]) => {
      const ItemIcon = Icon as React.ElementType;
      return <button key={String(key)} className={`nav-item ${route === key || key === "home" && (AUTO.includes(route) || STAGES.includes(route)) ? "active" : ""}`} onClick={() => { if (key === "retrieve") setSupplement(null); navigate(key as Route); }}><ItemIcon size={17} stroke={1.65} /><span>{String(label)}</span>{key === "home" && <Badge tone="blue">Pro</Badge>}</button>;
    })}</React.Fragment>)}</nav><div className="side-footer"><button className={`nav-item ${route === "settings" ? "active" : ""}`} onClick={() => navigate("settings")}><IconSettings size={17} /><span>设置</span></button><div className="service-panel"><div className="row between"><span>本机引擎</span><span><i className={`dot ${error ? "offline" : ""}`} />{error ? "未连接" : state?.settings.runtime.ffmpeg_ready ? "可用" : "待检查"}</span></div><div className="row between" style={{ marginTop: 8 }}><span>公共素材</span><span>{basics.library.available_video_count ? `${basics.library.available_video_count} 条` : state?.settings.runtime.library_ready ? `${state.settings.runtime.library_count} 条` : "待同步"}</span></div><div className="row between" style={{ marginTop: 8 }}><span>输出位置</span><span>本机工作区</span></div></div><div className="side-account"><IconDeviceDesktop size={18} /><span className="grow">{state?.auth.user?.username || "未登录"}</span><button className="icon-btn" aria-label="打开账号设置" onClick={() => navigate("settings")}><IconSettings size={14} /></button></div></div></aside>
    <main className="workspace"><header className="topbar"><div className="crumb"><span>智能剪辑端</span><IconChevronRight size={12} />{STAGES.includes(route) ? <><button className="text-btn" aria-label={automatic ? "返回自动创作工作台" : "返回手动创作列表"} onClick={backToMode}>{automatic ? "自动创作" : "手动创作"}</button><IconChevronRight size={12} />{work && <><span className="crumb-project" title={work.title}>{work.title}</span><IconChevronRight size={12} /></>}<strong>{NAMES[route]}</strong></> : <strong>{NAMES[route]}</strong>}</div><div className="top-tags"><span className="row"><IconLock size={12} />公共素材只读</span><span className="row"><IconDeviceDesktop size={13} />本机执行</span><button className="text-btn" onClick={() => navigate("settings")}>配置与服务状态</button></div></header>
      <div className="page" ref={pageRef}>{error && <><Banner tone="amber">{error} <button className="text-btn" onClick={() => void refresh()}>重新连接</button></Banner><div className="space" /></>}{state ? <>{route !== "settings" && !state.settings.library_root ? <><Header title="准备本机创作工作区" subtitle="先配置公共素材库和本机目录，再开始真实创作。" /><Button variant="primary" icon={IconSettings} onClick={() => navigate("settings")}>打开设置</Button></> : route !== "settings" && state.auth.required ? loginPage() : smartBlocked ? <Empty>当前为普通账号，请进入文案检索使用基础剪辑功能。</Empty> : <>{(route === "home" || AUTO.includes(route)) && modeTabs()}{AUTO.includes(route) && autoNav()}{page()}</>}</> : <Empty>正在连接本机引擎…</Empty>}</div>
      <footer className="status-footer"><span>{state?.settings.workspace_root || "本机智能工作区"}</span><span>智能剪辑端 v0.1.0 · 原声优先</span></footer></main></div>{toast && <div className="toast" role="status"><IconCheck size={17} />{toast}</div>}{dialogContent()}</div>;
}
